    }
    /// Whether [translateTexts] can run for the pair now (false below macOS 26).
    let translationReadyChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.tinglang_native_macos.TinglangHostApi.translationReady\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
