    /// event says when there is something new.
    let takeOpenedFilesChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.tinglang_native_macos.TinglangHostApi.takeOpenedFiles\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
