    } else {
      takeOpenedFilesChannel.setMessageHandler(nil)
    }
    /// Download state of each path, in the same order: `local`, `current`,
    /// `outdated`, `notDownloaded` or `missing`.
    let cloudItemStatesChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.tinglang_native_macos.TinglangHostApi.cloudItemStates\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
