    let cloudDownloadChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.tinglang_native_macos.TinglangHostApi.cloudDownload\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
