    /// This Mac's IOPlatformUUID (stays on the Mac), or null.
    let machineIdentifierChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.tinglang_native_macos.TinglangHostApi.machineIdentifier\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
